! <HET300>:
  RCONST(2303) = (khet_St(ihs_N2O5_H2O))
! <HET301>:
  RCONST(2304) = (khet_Tr(iht_N2O5))
! <HET610>:
  RCONST(2305) = (khet_St(ihs_HOCl_HCl))
! <HET620>:
  RCONST(2306) = (khet_St(ihs_ClNO3_HCl))
! <HET621>:
  RCONST(2307) = (khet_St(ihs_ClNO3_H2O))
! <HET622>:
  RCONST(2308) = (khet_St(ihs_N2O5_HCl))
! <HET710>:
  RCONST(2309) = (khet_St(ihs_HOBr_HBr))
! <HET720>:
  RCONST(2310) = (khet_St(ihs_BrNO3_H2O))
! <HET740>:
  RCONST(2311) = (khet_St(ihs_ClNO3_HBr))
! <HET741>:
  RCONST(2312) = (khet_St(ihs_BrNO3_HCl))
! <HET742>:
  RCONST(2313) = (khet_St(ihs_HOCl_HBr))
! <HET743>:
  RCONST(2314) = (khet_St(ihs_HOBr_HCl))
! <HET1001>:
  RCONST(2315) = (khet_Tr(iht_Hg)+khet_St(ihs_Hg))
! <HET1002>:
  RCONST(2316) = (khet_Tr(iht_RGM)+khet_St(ihs_RGM))
! <HET1003>:
  RCONST(2317) = (khet_Tr(iht_RGM)+khet_St(ihs_RGM))
! <HET1004>:
  RCONST(2318) = (khet_Tr(iht_RGM)+khet_St(ihs_RGM))
! <HET1005>:
  RCONST(2319) = (khet_Tr(iht_RGM)+khet_St(ihs_RGM))
! <HET1006>:
  RCONST(2320) = (khet_Tr(iht_RGM)+khet_St(ihs_RGM))
! <HET1007>:
  RCONST(2321) = (khet_Tr(iht_RGM)+khet_St(ihs_RGM))
! <HET1008>:
  RCONST(2322) = (khet_Tr(iht_RGM)+khet_St(ihs_RGM))
! <HET1009>:
