END SUBROUTINE UPDATE_RCONST
! ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
! 
! Update_PHOTO - function to update photolytical rate constants
!   Arguments :
! 
! ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

SUBROUTINE Update_PHOTO ( )


! Begin inlined code from F90_RCONST_USE


! End inlined code from F90_RCONST_USE


! Begin inlined code from F90_RCONST


  ! start of USE statements from messy_mecca_kpp.kpp
  USE messy_main_constants_mem  ! atm2Pa, N_A, R_gas
  USE messy_cmn_photol_mem      ! IP_MAX, ip_*, jname
  USE messy_main_tools_kinetics ! ELEMENTAL rate coefficient functions
  ! end of USE statements from messy_mecca_kpp.kpp

  ! start of executable statements
  ! define some rate constants here if the expressions are too long
  ! for kpp or if they are used more than once
  ! --------------------------------------------------------------------------
  ! inorganic and C1 chemistry:
  k_HO2_HO2    = (3.0E-13*EXP(460./temp)+2.1E-33*EXP(920./temp)*cair)* &
                 (1.+1.4E-21*EXP(2200./temp)*C(ind_H2O))
  k_NO2_O3P    = k_3rd_jpl_activation(temp,cair,3.4E-31,1.6,2.3E-11,0.2,5.3E-12,-200.) ! ref3500
  k_NO3_NO2    = k_3rd(temp,cair,2.4E-30,3.0,1.6E-12,-0.1,0.6){B'1.1} ! ref3500
  k_NO2_HO2    = k_3rd(temp,cair,1.9E-31,3.4,4.0E-12,0.3,0.6){B'1.06} ! ref3500
  k_HNO3_OH    = 1.32E-14*EXP(527./temp) + 1./ & ! "All data" in Tab. 1 of ref3325
                 ( 1./(7.39E-32*EXP(453./temp)*cair) + &
                 1./(9.73E-17*EXP(1910./temp)) ){B'1.15} ! 15 % ref3325, p. 2389
  k_CH3OOH_OH  = 5.3E-12*EXP(190./temp){B'B'0.30}
  k_CH3CO2H_OH = 4.0E-14*EXP(850./temp)
  k_ClO_ClO    = k_3rd(temp,cair,1.9E-32,3.6,3.7E-12,1.6,0.6){B'1.15} ! ref3500
  k_BrO_NO2    = k_3rd_iupac(temp,cair,4.7E-31{B'B'0.1},3.1,1.8E-11{B'B'0.1},0.0,0.4)
  ! JPL: k_BrO_NO2   = k_3rd(temp,cair,5.5E-31,3.1,6.6E-12,2.9,0.6){B'1.2} ! ref3500
  k_I_NO2      = k_3rd_iupac(temp,cair,3.0E-31{B'B'0.2},1.0,6.6E-11{B'B'0.3},0.0,0.63)
  ! for numerical reasons, the expression is multiplied by 1e30/1e30
  k_DMS_OH     = 1.E-9*EXP(5820./temp)*C(ind_O2)/ &
                 (1.E30+5.*EXP(6280./temp)*C(ind_O2)){B'B'0.30}
  k_CH2OO_SO2  = 3.66E-11{B'} ! average of 3.9E-11 + 3.42E-11
  k_O3s = (1.7E-12*EXP(-940./temp)) * C(ind_OH) &  ! <G2104>
        + (1.E-14*EXP(-490./temp)) * C(ind_HO2) &  ! <G2107>
        + jx(ip_O1D) * 2.2E-10 * C(ind_H2O) &      !
        / ( 3.2E-11*EXP(70./temp)*C(ind_O2)   &
           + 1.8E-11*EXP(110./temp)*C(ind_N2) &
           + 2.2E-10*C(ind_H2O) )
  ! new methane chemistry:
  ! branching ratio for methyl nitrate according to Butkovskaya et al.,
  ! (ref3177) but reduced according to Flocke et al. (ref3164)
  ! fit of data according to Lindemann-Hinshelwood scheme by J. Crowley
  ! http://iupac.pole-ether.fr/datasheets/pdf/ROO_1_CH3O2_NO.pdf
  beta_null_CH3NO3 = 0.00295 + 5.15E-22*cair*(temp/298)**(7.4)
  beta_inf_CH3NO3  = 0.022
  beta_CH3NO3      = (beta_null_CH3NO3 * beta_inf_CH3NO3) /&
                     (beta_null_CH3NO3 + beta_inf_CH3NO3) / 10.
  k_NO2_CH3O2      = k_3rd(temp,cair,1.0E-30,4.8,7.3E-12,2.1,0.6){B'1.5} ! ref3500
  k_C6H5O2_NO2     = k_NO2_CH3O2 ! Consistent with ref3167 that set 1E-12 as lower limit at 298 K and 1 bar.
  k_CH2OO_NO2      = 4.25E-12{B'} ! average of 7.E-12 and 1.5E-12
  ! branching ratio for ethylnitrate formation according to Butkovskaya ref3170
  ! ratio transformed from beta = k1b/k1a to beta_C2H5NO3 = (1-(1+beta)^(-1))
  beta_C2H5NO3    = (1-1/(1+1.E-2*(3.88e-3*cair/2.46e19*760.+.365)*(1+1500.*(1/temp -1/298.))))
  ! --------------------------------------------------------------------------
  ! only for mim1, see mim1.rpl:
  ! op_kg_20110805+ for HO2 + NO -> HNO3 (butkovskaya_*.rpl)
  alpha_NO_HO2 = C(ind_H2O)*6.6E-27*temp*EXP(3700./temp)
  beta_NO_HO2  = MAX(((530./temp)+(press*4.8004E-6)-1.73)*0.01,0._dp)
  k0_NO_HO2    = 3.5E-12*EXP(250./temp)
  ! without humidity correction
  k2d_NO_HO2   = (beta_NO_HO2*k0_NO_HO2)/(1.+beta_NO_HO2)
  k1d_NO_HO2   = k0_NO_HO2 - k2d_NO_HO2
  ! ju_te_20200626+
  !! with humidity correction
  !k2w_NO_HO2   = (beta_NO_HO2*k0_NO_HO2*(1.+42.*alpha_NO_HO2))/ &
  !               ((1.+alpha_NO_HO2)*(1.+beta_NO_HO2))
  ! with humidity correction according to Duncianu et al. (ref3537):
  k2w_NO_HO2   = ((beta_NO_HO2*k0_NO_HO2*(1.+42.*alpha_NO_HO2))/ &
                 ((1.+alpha_NO_HO2)*(1.+beta_NO_HO2)))/2.0_dp 
  ! ju_te_20200626-
  k1w_NO_HO2   = k0_NO_HO2 - k2w_NO_HO2
  ! op_kg_20110805-
  k_PrO2_HO2   = 1.9E-13*EXP(1300./temp)
  k_PrO2_NO    = 2.7E-12*EXP(360./temp)
  k_PrO2_CH3O2 = 9.46E-14*EXP(431./temp)
  f_BrO_CH3O2 = 0.8{B'1.25}/1.1 ! 0.8+/-0.2
  ! end of mim1 block
  ! --------------------------------------------------------------------------
  ! NO2 + OH:
  ! branching ratio:
  alpha_HOONO = ((3.3E-20*(temp/300.)**(-4.4))*cair * 0.29) / &
                ((3.3E-20*(temp/300.)**(-4.4))*cair + 0.29) * &
                10**(LOG10(0.39)/(1+(LOG10((3.3E-20*(temp/300.)**(-4.4)) &
                *cair/0.29)/(0.75-1.27*LOG10(0.39)))**(2.0)))+0.035
  ! low-pressure limit:
  k_NO2_OH_lpl = C(ind_N2)  *  2.6E-30*(temp/300.)**(-3.6) + &
                 C(ind_O2)  *  2.0E-30*(temp/300.)**(-3.6) + &
                 C(ind_H2O) * 15.9E-30*(temp/300.)**(-3.4)
  ! high-pressure limit:
  k_NO2_OH_hpl = 6.3E-11
  ! broadening factor:
  k_NO2_OH_logF = log10(0.39) / &
                  (1.+(log10(k_NO2_OH_lpl/k_NO2_OH_hpl)/(0.75-1.27*log10(0.39)))**2)
  ! rate constant:
  k_NO2_OH = ((k_NO2_OH_lpl*k_NO2_OH_hpl) / (k_NO2_OH_lpl+k_NO2_OH_hpl)) * &
             10.**k_NO2_OH_logF
  ! --------------------------------------------------------------------------
  ! SO2 + OH:
  ! low-pressure limit:
  k_SO2_OH_lpl = (cair-C(ind_H2O)) * 3.03E-31*(temp/300.)**(-4.1) + &
                 C(ind_H2O)        * 1.65E-30*(temp/300.)**(-4.9)
  ! high-pressure limit:
  k_SO2_OH_hpl = 2.0E-12
  ! broadening factor:
  k_SO2_OH_logF = log10(0.58) / &
                  (1.+(log10(k_SO2_OH_lpl/k_SO2_OH_hpl)/(0.75-1.27*log10(0.58)))**2)
  ! rate constant:
  k_SO2_OH = ((k_SO2_OH_lpl*k_SO2_OH_hpl) / (k_SO2_OH_lpl+k_SO2_OH_hpl)) * &
             10.**k_SO2_OH_logF
  ! --------------------------------------------------------------------------
  ! ju_te_20200626+ Equilibrium constant for the MACRO2-H2O complex (Xing, ref3538)
  k_eq_RO2 = 1.89E-18    
  f_RO2 = 1./(K_eq_RO2*C(ind_H2O) +1)   
  ! ju_te_20200626-
  k_CH3CO_O2   = k_3rd_jpl_activation(temp,cair,2.0E-29,2.6,5.3E-12,0.7,6.6E-14,-800.) ! ref3500
  k_CH3CO3_NO2 = k_3rd(temp,cair,7.3E-29,4.1,9.5E-12,1.6,0.6){B'1.1} ! ref3500
  k_PAN_M      = k_CH3CO3_NO2/(9.0E-29{B'1.2}*EXP(14000./temp)) ! ref3500
  ! rate coefficients from the MCM:
  KDEC    = 1.E6 ! moved here from parameters to avoid renaming to k_dec 
                 ! required by medina parser for parameters
  KRO2NO  = 2.54E-12{B'}*EXP(360./temp)
  KAPNO   = 8.10E-12{B'}*EXP(270./temp)  ! CH3CO3 + NO
  KRO2NO3 = 2.30E-12{B'} ! ref2419
  KNO3AL  = 1.4E-12{B'1.3}*EXP(-1900./temp)
  ! updated rate constant for the RCO3+HO2 reactions
  ! (GroC, PhD Thesis, ref3195)
  ! except CH3CO3+HO2 that is taken from GroC ref3156
  KAPHO2  = 5.20E-13*EXP(980./temp)*1.865 ! at 298K k(hoch2co3 + ho2) = 2.6(+-0.4)E-11 scaled with IUPAC T-dependent expression
  ! Rate constants for the permutation reaction formalism
  ! calculated as in the permutation reaction formalism of MCM
  ! k_RO2 = 2.*(KRO2self*k_CH3O2)^0.5
  ! k_RO2self are taken from IUPAC recommendations unless noted otherwise
  k_CH3O2     = 1.03E-13{B'B'0.12}*EXP(365./temp) ! CH3O2 + CH3O2 (IUPAC)
  ! Acyl peroxy radicals
  k_RO2RCO3   = 2.*2.E-12{B'B'0.15}*EXP(500./temp) ! K17 for the CH3CO3 + CH3O2 reaction directly taken from ref. 1759. Old MCM value 1.00E-11 at 298 K.
  ! Alkyl radicals (unsubstituted, > C3)
  k_RO2pRO2   = 2.*(1.E-12{B'}*k_CH3O2)**(.5)                      ! Model compound (CH3)2CHCH2O2 (isobutyl, ref3210). Old MCM value 1.30E-12 at 298 K.
  k_RO2sRO2   = 2.*(1.6E-12{B'B'0.3}*EXP(-2200./temp)*k_CH3O2)**(.5)! Model compound i-C3H7O2 (ref3175). Old MCM value 2.50E-13 at 298 K.
  k_RO2tRO2   = 2.*3.8E-13{B'B'0.6}*EXP(-1430./temp)                ! Model reaction t-C4H9O2 + CH3O2. Old MCM value 6.70E-15 at 298 K.
  ! Alkyl radical with either O or Cl in beta
  k_RO2pORO2  = 2.*7.5E-13{B'}*EXP(500./temp)                      ! Model reaction CH3COCH2O2 + CH3O2 (ref3175). Old MCM value 2.00E-12
  k_RO2sORO2  = 2.*(7.7E-15{B'B'0.2}*EXP(1330./temp)*k_CH3O2)**(.5) ! Model compound CH3CH(OH)CH(O2)CH3 (ref3175). Old MCM value 8.80E-13 at 298 K.
  k_RO2tORO2  = 2.*(4.7E-13{B'}*EXP(-1420./temp)*k_CH3O2)**(.5)    ! Model compound (CH3)2C(OH)CO2(CH3)2 (ref3175). Old MCM value 9.20E-14 at 298 K.
  ! Allyl- and beta-hydroxy alkyl radicals
  k_RO2LISOPACO2 = 2.*((2.8E-12{B'}+3.9E-12{B'})/2.*k_CH3O2)**(.5)  ! Model compound ISOPAO2 and ISOPCO2. Old MCM value 2.0E-12 at 298 K. K15 average from MCM ref. 2419
  k_RO2ISOPBO2   = 2.*(6.9E-14{B'}*k_CH3O2)**(.5)                  ! Model compound ISOPBO2. Old MCM value 8.0E-13 at 298 K. K15 from MCM ref. 2419
  k_RO2ISOPDO2   = 2.*(4.8E-12{B'}*k_CH3O2)**(.5)                  ! Model compound ISOPDO2. Old MCM value 8.0E-13 at 298 K. K15 from MCM ref. 2419
  ! T-dependent H-abstraction group rate constants
  k_p          = 4.49E-18{B'}*temp*temp*EXP(-320./temp) ! Kwok and Atkinson, ref3194
  k_s          = 4.50E-18{B'}*temp*temp*EXP(253./temp)  ! Kwok and Atkinson, ref3194
  k_t          = 2.12E-18{B'}*temp*temp*EXP(696./temp)  ! Kwok and Atkinson, ref3194
  k_ROHRO      = 2.1E-18{B'}*temp*temp*EXP(-85./temp)   ! Kwok and Atkinson, ref3194
  k_ROOHRO     = 0.6*k_CH3OOH_OH
  k_CO2H       = 0.7*k_CH3CO2H_OH
  ! T-dependent OH-addition rate constants
  k_adp        = 4.5E-12{B'}*(temp/300.)**(-0.85)                        ! 1/2 k(OH + C2H4), high pressure limit IUPAC as in Peeters et al. 2007
  k_ads        = 0.25{B'}*(1.1E-11*EXP(485./temp)+1.0E-11*EXP(553./temp)) ! 1/2 * k_av(OH + cis/trans 2-butene) as in Peeters et al. 2007
  k_adt        = 1.922E-11{B'}*EXP(450./temp) - k_ads                    ! k(OH + 2-methyl-2-butene) - k_ads
  k_hsb         = 1.52E11{B'}*EXP(-9512./temp)*1. ! 1,5-H-shift Peeters et al(2009) 0.003533 s-1 at 303K
  k_hsd         = 6.08E10{B'}*EXP(-8893./temp)*1. ! 1,5-H-shift Peeters et al(2009) 0.0109 s-1 at 303K
  ! 1,6-H-shift for ZISOPAO2 and ZISOPCO2
  k_16hsz14     = 5.47E15*EXP(-12200./temp)*EXP(1.0E8/temp**3) ! Novelli et al., ACP, 2020
  k_16hsz41     = 2.40E9*EXP(-7160./temp)*EXP(1.0e8/temp**3)   ! Novelli et al., ACP, 2020
  k_16hs        = (k_16hsz14*k_16hsz41)**(.5)
  k_15hsdhb     = 2.9E7*exp(-5297./temp)                       ! Novelli et al., ACP, 2020
  ! 1,4-H-shift involving an aldehydic hydrogen
  !k_14hsal = 2.9E7{B'}*exp(-5297/temp) ! Crounse ref3331 barrier 19 kcal/mol => ~ 0.5 s-1 at 295K
  k_14hsal      = (2.86265925589E-3*temp)**20.52*exp(1669./temp) ! Novelli et al., ACP, 2020. Modified expression in order to avoid numerical problems. Original reported expression: 6.5E-53*(temp**20.52)*exp(1669./temp)
  !k_14hsal      = 2.9E7{B'}*exp(-1*(5297+705)/temp) ! CCSD(T)/aug-Schartz4(DT)//M05-2X/6-311G(d,p)) yields a barrier of 20.39 (L. Vereecken 2013) => ~ 0.04 s-1 at 295K
  k_15hs24vynal = k_16hsz14 * exp(-3500/(1.987*temp)) ! adding 3.5 kcal to the barrier of 1,6-H-shift as from SAR by L. Vereecken
  k_15hs42vynal = k_16hsz41 * exp(-3500/(1.987*temp))
  k_hydec       = 6.e14{B'}*exp(-16000./(1.98588*temp)) ! in cal Ea from Nguyen et al(2009) A from Baulch et al(2005)
  ! Rate constants for the formic acid production via vinyl alcohol. Also used for some bigger and saturated aldehydes.
  k_VINOH_OH_HCOOH = 4.3E-11{B'} ! ref3179
  k_VINOH_OH_ALD   = 2.4E-11{B'} ! ref3179
  k_VINOH_HCOOH    = 0.{B'} ! pers. comm. Luc Vereecken (email 2021-04-14), see also CHANGELOG
  k_ALD_HCOOH      = 0.{B'} ! pers. comm. Luc Vereecken (email 2021-04-14), see also CHANGELOG
  j_IC3H7NO3   = jx(ip_IC3H7NO3)
  j_ACETOL     = 0.65*jx(ip_ACETOL) ! quantum yield of 0.65 is from ref2510
  j_HPALD      = (jx(ip_CH3OOH)+ jx(ip_MACR)/(2.*1.95E-3)) ! mcm.leeds.ac.uk/MCM/parameters/photolysis.htt
  j_ketene     = jx(ip_MVK)/0.004

  ! iodine:
  k_IO_OIO  = (4.687E-10 - 1.3855E-5*exp(-0.75*press/162.265) + 5.51868E-10*exp(-0.75*press/19932.8)) &
              * exp((-3.31E-3 - 5.14E-3*exp(-0.75*press/32568.711) - 4.44E-3*exp(-0.75*press/4081.609)) *temp) ! ref3760
  k_OIO_OIO = (1.1659E-9 - 7.79644E-10*exp(-0.75*press/2209.281) + 1.03779E-9*exp(-0.75*press/56815.381)) &
              * exp((-8.13E-3 - 3.82E-3*exp(-0.75*press/4557.591) - 6.43E-3*exp(-0.75*press/41795.061)) *temp) ! ref3760
  k_I2O2a   = (2.55335E11 - 4.41888E7*0.75*press + 8561.86*(0.75*press)**2 + 1.421881E-2*(0.75*press)**3) &
              * exp((-11466.82304 + 597.01334*exp(-0.75*press/138262.325) - 167.3391*exp(-0.75*press/4375.089)) *temp) ! ref3760
  k_I2O4    = (-1.92626E14 + 4.67414E11*0.75*press - 3.68651E4*(0.75*press)**2 - 3.09109*(0.75*press)**3) &
              * exp((-12302.15294 + 252.78367*exp(-0.75*press/4612.733) + 437.62868*exp(-0.75*press/42844.13)) *temp) ! ref3760

  RO2 = 0.
  IF (ind_LISOPACO2>0)            RO2 = RO2 + C(ind_LISOPACO2)
  IF (ind_LDISOPACO2>0)           RO2 = RO2 + C(ind_LDISOPACO2)
  IF (ind_ISOPBO2>0)              RO2 = RO2 + C(ind_ISOPBO2)
  IF (ind_ISOPDO2>0)              RO2 = RO2 + C(ind_ISOPDO2)
  IF (ind_LISOPEFO2>0)            RO2 = RO2 + C(ind_LISOPEFO2)
  IF (ind_NISOPO2>0)              RO2 = RO2 + C(ind_NISOPO2)
  IF (ind_LHC4ACCO3>0)            RO2 = RO2 + C(ind_LHC4ACCO3)
  IF (ind_LC578O2>0)              RO2 = RO2 + C(ind_LC578O2)
  IF (ind_C59O2>0)                RO2 = RO2 + C(ind_C59O2)
  IF (ind_LNISO3>0)               RO2 = RO2 + C(ind_LNISO3)
  IF (ind_CH3O2>0)                RO2 = RO2 + C(ind_CH3O2)
  IF (ind_HOCH2O2>0)              RO2 = RO2 + C(ind_HOCH2O2)
  IF (ind_CH3CO3>0)               RO2 = RO2 + C(ind_CH3CO3)
  IF (ind_C2H5O2>0)               RO2 = RO2 + C(ind_C2H5O2)
  IF (ind_HOCH2CO3>0)             RO2 = RO2 + C(ind_HOCH2CO3)
  IF (ind_HYPROPO2>0)             RO2 = RO2 + C(ind_HYPROPO2)
  IF (ind_LBUT1ENO2>0)            RO2 = RO2 + C(ind_LBUT1ENO2)
  IF (ind_BUT2OLO2>0)             RO2 = RO2 + C(ind_BUT2OLO2)
  IF (ind_HCOCO3>0)               RO2 = RO2 + C(ind_HCOCO3)
  IF (ind_CO2H3CO3>0)             RO2 = RO2 + C(ind_CO2H3CO3)
  IF (ind_LHMVKABO2>0)            RO2 = RO2 + C(ind_LHMVKABO2)
  IF (ind_MACO3>0)                RO2 = RO2 + C(ind_MACO3)
  IF (ind_MACRO2>0)               RO2 = RO2 + C(ind_MACRO2)
  IF (ind_PRONO3BO2>0)            RO2 = RO2 + C(ind_PRONO3BO2)
  IF (ind_HOCH2CH2O2>0)           RO2 = RO2 + C(ind_HOCH2CH2O2)
  IF (ind_CH3COCH2O2>0)           RO2 = RO2 + C(ind_CH3COCH2O2)
  IF (ind_IC3H7O2>0)              RO2 = RO2 + C(ind_IC3H7O2)
  IF (ind_NC3H7O2>0)              RO2 = RO2 + C(ind_NC3H7O2)
  IF (ind_LC4H9O2>0)              RO2 = RO2 + C(ind_LC4H9O2)
  IF (ind_TC4H9O2>0)              RO2 = RO2 + C(ind_TC4H9O2)
